1	/**
2	Based on https://github.com/brc-dd/iron-webcrypto/tree/v1.2.1
3	Copyright (c) 2021 Divyansh Singh.
4	https://github.com/brc-dd/iron-webcrypto/blob/v1.2.1/LICENSE.md
5	
6	Based on https://github.com/hapijs/iron/tree/v7.0.1
7	Copyright (c) 2012-2022, Project contributors Copyright (c) 2012-2020, Sideway Inc All rights reserved.
8	https://github.com/hapijs/iron/blob/v7.0.1/LICENSE.md
9	 */
10	
11	import { base64Decode, base64Encode, textDecoder, textEncoder } from "./encoding.ts";
12	
13	/** The default encryption and integrity settings. */
14	export const defaults: Readonly<SealOptions> = /* @__PURE__ */ Object.freeze({
15	  ttl: 0,
16	  timestampSkewSec: 60,
17	  localtimeOffsetMsec: 0,
18	  encryption: /* @__PURE__ */ Object.freeze({
19	    saltBits: 256,
20	    algorithm: "aes-256-cbc",
21	    iterations: 8192,
22	    minPasswordlength: 32,
23	  }),
24	  integrity: /* @__PURE__ */ Object.freeze({
25	    saltBits: 256,
26	    algorithm: "sha256",
27	    iterations: 8192,
28	    minPasswordlength: 32,
29	  }),
30	});
31	
32	/** Configuration of each supported algorithm. */
33	export const algorithms = /* @__PURE__ */ Object.freeze({
34	  "aes-128-ctr": /* @__PURE__ */ Object.freeze({
35	    keyBits: 128,
36	    ivBits: 128,
37	    name: "AES-CTR",
38	  }),
39	  "aes-256-cbc": /* @__PURE__ */ Object.freeze({
40	    keyBits: 256,
41	    ivBits: 128,
42	    name: "AES-CBC",
43	  }),
44	  sha256: /* @__PURE__ */ Object.freeze({
45	    keyBits: 256,
46	    ivBits: 128,
47	    name: "SHA-256",
48	  }),
49	}) as Record<string, { keyBits: number; ivBits: number; name: string }>;
50	
51	/** MAC normalization format version. */
52	export const macFormatVersion = "2";
53	
54	/** MAC normalization prefix. */
55	export const macPrefix = "Fe26.2"; // `Fe26.${macFormatVersion}`
56	
57	/** Serializes, encrypts, and signs objects into an iron protocol string. */
58	export async function seal(
59	  object: Readonly<unknown>,
60	  password: Readonly<RawPassword>,
61	  opts: Readonly<SealOptions>,
62	): Promise<string> {
63	  const now = Date.now() + (opts.localtimeOffsetMsec || 0);
64	
65	  if (!password) {
66	    throw new Error("Empty password");
67	  }
68	  const { id = "", encryption, integrity } = normalizePassword(password);
69	  if (id && !/^\w+$/.test(id)) {
70	    throw new Error("Invalid password id");
71	  }
72	
73	  // prettier-ignore
74	  const { encrypted, key } = await encrypt(encryption, opts.encryption, JSON.stringify(object));
75	
76	  const encryptedB64 = base64Encode(encrypted);
77	  const iv = base64Encode(key.iv);
78	  const expiration = opts.ttl ? now + opts.ttl : "";
79	  const macBaseString = `${macPrefix}*${id}*${key.salt}*${iv}*${encryptedB64}*${expiration}`;
80	
81	  const mac = await hmacWithPassword(integrity, opts.integrity, macBaseString);
82	  const sealed = `${macBaseString}*${mac.salt}*${mac.digest}`;
83	  return sealed;
84	}
85	
86	/** Verifies, decrypts, and reconstruct an iron protocol string into an object. */
87	export async function unseal(
88	  sealed: string,
89	  password: Password | PasswordHash,
90	  opts: Readonly<SealOptions>,
91	): Promise<unknown> {
92	  const now = Date.now() + (opts.localtimeOffsetMsec || 0);
93	
94	  if (!password) {
95	    throw new Error("Empty password");
96	  }
97	
98	  const parts = sealed.split("*");
99	  if (parts.length !== 8) {
100	    throw new Error("Incorrect number of sealed components");
101	  }
102	  // prettier-ignore
103	  const [prefix, passwordId, encryptionSalt, encryptionIv, encryptedB64, expiration, hmacSalt, hmac] = parts;
104	  const macBaseString = `${prefix}*${passwordId}*${encryptionSalt}*${encryptionIv}*${encryptedB64}*${expiration}`;
105	
106	  if (macPrefix !== prefix) {
107	    throw new Error("Wrong mac prefix");
108	  }
109	
110	  if (expiration) {
111	    if (!/^\d+$/.test(expiration)) {
112	      throw new Error("Invalid expiration");
113	    }
114	    const exp = Number.parseInt(expiration, 10);
115	    if (exp <= now - opts.timestampSkewSec * 1000) {
116	      throw new Error("Expired seal");
117	    }
118	  }
119	
120	  let pass: RawPassword = "";
121	  const _passwordId = passwordId || "default";
122	  if (typeof password === "string" || password instanceof Uint8Array) {
123	    pass = password;
124	  } else if (_passwordId in password) {
125	    pass = password[_passwordId]!;
126	  } else {
127	    throw new Error(`Cannot find password: ${_passwordId}`);
128	  }
129	
130	  pass = normalizePassword(pass);
131	
132	  // prettier-ignore
133	  const mac = await hmacWithPassword(pass.integrity, { ...opts.integrity, salt: hmacSalt }, macBaseString);
134	
135	  if (!fixedTimeComparison(mac.digest, hmac)) {
136	    throw new Error("Bad hmac value");
137	  }
138	
139	  const encrypted = base64Decode(encryptedB64);
140	
141	  const decryptOptions: GenerateKeyOptions<EncryptionAlgorithm> = {
142	    ...opts.encryption,
143	    salt: encryptionSalt,
144	    iv: base64Decode(encryptionIv),
145	  };
146	
147	  const decrypted = await decrypt(pass.encryption, decryptOptions, encrypted);
148	
149	  return decrypted ? JSON.parse(decrypted) : null;
150	}
151	
152	// --- hmac ---
153	
154	/** Calculates a HMAC digest. */
155	export async function hmacWithPassword(
156	  password: Readonly<Password>,
157	  options: Readonly<GenerateKeyOptions<IntegrityAlgorithm>>,
158	  data: string,
159	): Promise<HMacResult> {
160	  const key = await generateKey(password, { ...options, hmac: true });
161	  const textBuffer = textEncoder.encode(data);
162	  // prettier-ignore
163	  const signed = await crypto.subtle.sign({ name: "HMAC" }, key.key, textBuffer);
164	  const digest = base64Encode(new Uint8Array(signed));
165	  return { digest, salt: key.salt };
166	}
167	
168	// --- key generation ---
169	
170	/** Generates a key from the password. */
171	export async function generateKey(password: Password, options: GenerateKeyOptions): Promise<Key> {
172	  if (!password?.length) {
173	    throw new Error("Empty password");
174	  }
175	
176	  if (options == null || typeof options !== "object") throw new Error("Bad options");
177	  if (!(options.algorithm in algorithms))
178	    throw new Error(`Unknown algorithm: ${options.algorithm}`);
179	
180	  const algorithm = algorithms[options.algorithm];
181	
182	  let resultKey: Key["key"];
183	  let resultSalt: Key["salt"];
184	  let resultIV: Key["iv"];
185	
186	  const hmac = options.hmac ?? false;
187	  // prettier-ignore
188	  const id = hmac ? { name: "HMAC", hash: algorithm.name } : { name: algorithm.name };
189	  const usage: KeyUsage[] = hmac ? ["sign", "verify"] : ["encrypt", "decrypt"];
190	
191	  if (typeof password === "string") {
192	    if (password.length < options.minPasswordlength) {
193	      throw new Error(
194	        `Password string too short (min ${options.minPasswordlength} characters required)`,
195	      );
196	    }
197	    let { salt = "" } = options;
198	    if (!salt) {
199	      const { saltBits = 0 } = options;
200	      if (!saltBits) throw new Error("Missing salt and saltBits options");
201	      const randomSalt = randomBits(saltBits);
202	      salt = [...new Uint8Array(randomSalt)].map((x) => x.toString(16).padStart(2, "0")).join("");
203	    }
204	
205	    // prettier-ignore
206	    const derivedKey = await pbkdf2(password, salt, options.iterations, algorithm.keyBits / 8, "SHA-1");
207	    // prettier-ignore
208	    const importedEncryptionKey = await crypto.subtle.importKey("raw", derivedKey, id, false, usage);
209	    resultKey = importedEncryptionKey;
210	    resultSalt = salt;
211	  } else {
212	    if (password.length < algorithm.keyBits / 8) {
213	      throw new Error("Key buffer (password) too small");
214	    }
215	    // prettier-ignore
216	    resultKey = await crypto.subtle.importKey("raw", password, id, false, usage);
217	    resultSalt = "";
218	  }
219	
220	  if (options.iv) {
221	    resultIV = options.iv;
222	  } else if ("ivBits" in algorithm) {
223	    resultIV = randomBits(algorithm.ivBits);
224	  } else {
225	    throw new Error("Missing IV");
226	  }
227	
228	  return {
229	    key: resultKey,
230	    salt: resultSalt,
231	    iv: resultIV,
232	  } satisfies Key;
233	}
234	
235	/** Provides an asynchronous Password-Based Key Derivation Function 2 (PBKDF2) implementation. */
236	async function pbkdf2(
237	  password: string,
238	  salt: string,
239	  iterations: number,
240	  keyLength: number,
241	  hash: HashAlgorithmIdentifier,
242	): Promise<ArrayBuffer> {
243	  const passwordBuffer = textEncoder.encode(password);
244	  // prettier-ignore
245	  const importedKey = await crypto.subtle.importKey("raw", passwordBuffer, { name: "PBKDF2" }, false, ["deriveBits"]);
246	  const saltBuffer = textEncoder.encode(salt);
247	  const params = { name: "PBKDF2", hash, salt: saltBuffer, iterations };
248	  // prettier-ignore
249	  const derivation = await crypto.subtle.deriveBits(params, importedKey, keyLength * 8);
250	  return derivation;
251	}
252	
253	// --- encrypt/decrypt ---
254	
255	export async function encrypt(
256	  password: Password,
257	  options: GenerateKeyOptions<EncryptionAlgorithm>,
258	  data: string,
259	): Promise<{ encrypted: Uint8Array<ArrayBuffer>; key: Key }> {
260	  const key = await generateKey(password, options);
261	  const encrypted = await crypto.subtle.encrypt(...getEncryptParams(options.algorithm, key, data));
262	  return { encrypted: new Uint8Array(encrypted), key };
263	}
264	
265	export async function decrypt(
266	  password: Password,
267	  options: GenerateKeyOptions<EncryptionAlgorithm>,
268	  data: Uint8Array<ArrayBuffer> | string,
269	): Promise<string> {
270	  const key = await generateKey(password, options);
271	  const decrypted = await crypto.subtle.decrypt(...getEncryptParams(options.algorithm, key, data));
272	  return textDecoder.decode(decrypted);
273	}
274	
275	function getEncryptParams(
276	  algorithm: EncryptionAlgorithm,
277	  key: Key,
278	  data: Uint8Array<ArrayBuffer> | string,
279	): [AesCbcParams | AesCtrParams, CryptoKey, Uint8Array<ArrayBuffer>] {
280	  return [
281	    algorithm === "aes-128-ctr"
282	      ? ({
283	          name: "AES-CTR",
284	          counter: key.iv,
285	          length: 128,
286	        } satisfies AesCtrParams)
287	      : ({ name: "AES-CBC", iv: key.iv } satisfies AesCbcParams),
288	    key.key,
289	    typeof data === "string" ? textEncoder.encode(data) : data,
290	  ];
291	}
292	
293	// --- other utils ---
294	
295	/** Returns true if `a` is equal to `b`, without leaking timing information that would allow an attacker to guess one of the values. */
296	function fixedTimeComparison(a: string, b: string): boolean {
297	  let mismatch = a.length === b.length ? 0 : 1;
298	  if (mismatch) b = a;
299	  for (let i = 0; i < a.length; i += 1) mismatch |= a.charCodeAt(i) ^ b.charCodeAt(i);
300	  return mismatch === 0;
301	}
302	
303	/** Normalizes a password parameter. */
304	function normalizePassword(password: RawPassword) {
305	  if (typeof password === "string" || password instanceof Uint8Array) {
306	    return { encryption: password, integrity: password };
307	  }
308	  if ("secret" in password) {
309	    return {
310	      id: password.id,
311	      encryption: password.secret,
312	      integrity: password.secret,
313	    };
314	  }
315	  return {
316	    id: password.id,
317	    encryption: password.encryption,
318	    integrity: password.integrity,
319	  };
320	}
321	
322	/** Generate cryptographically strong pseudorandom bits. */
323	export function randomBits(bits: number): Uint8Array<ArrayBuffer> {
324	  if (bits < 1) throw new Error("Invalid random bits count");
325	  const bytes = Math.ceil(bits / 8);
326	  return randomBytes(bytes);
327	}
328	
329	/** Generates cryptographically strong pseudorandom bytes. */
330	function randomBytes(size: number): Uint8Array<ArrayBuffer> {
331	  const bytes = new Uint8Array(size);
332	  crypto.getRandomValues(bytes);
333	  return bytes;
334	}
335	
336	// --- Types ---
337	
338	/** Algorithm used for encryption and decryption. */
339	type EncryptionAlgorithm = "aes-128-ctr" | "aes-256-cbc";
340	
341	/** Algorithm used for integrity verification. */
342	export type IntegrityAlgorithm = "sha256";
343	
344	/** @internal */
345	type _Algorithm = EncryptionAlgorithm | IntegrityAlgorithm;
346	
347	/**
348	 * Options for customizing the key derivation algorithm used to generate encryption and integrity verification keys as well as the algorithms and salt sizes used.
349	 */
350	export type SealOptions = Readonly<{
351	  /** Encryption step options. */
352	  encryption: SealOptionsSub<EncryptionAlgorithm>;
353	
354	  /** Integrity step options. */
355	  integrity: SealOptionsSub<IntegrityAlgorithm>;
356	
357	  /*Sealed object lifetime in milliseconds where 0 means forever. Defaults to 0. */
358	  ttl: number;
359	
360	  /** Number of seconds of permitted clock skew for incoming expirations. Defaults to 60 seconds. */
361	  timestampSkewSec: number;
362	
363	  /**
364	   * Local clock time offset, expressed in number of milliseconds (positive or negative). Defaults to 0.
365	   */
366	  localtimeOffsetMsec: number;
367	}>;
368	
369	/** `seal()` method options. */
370	type SealOptionsSub<Algorithm extends _Algorithm = _Algorithm> = Readonly<{
371	  /** The length of the salt (random buffer used to ensure that two identical objects will generate a different encrypted result). Defaults to 256. */
372	  saltBits: number;
373	
374	  /** The algorithm used. Defaults to 'aes-256-cbc' for encryption and 'sha256' for integrity. */
375	  algorithm: Algorithm;
376	
377	  /** The number of iterations used to derive a key from the password. Defaults to 1. */
378	  iterations: number;
379	
380	  /** Minimum password size. Defaults to 32. */
381	  minPasswordlength: number;
382	}>;
383	
384	/** Password secret string or buffer.*/
385	type Password = Uint8Array<ArrayBuffer> | string;
386	
387	/** `generateKey()` method options. */
388	export type GenerateKeyOptions<Algorithm extends _Algorithm = _Algorithm> = Pick<
389	  SealOptionsSub<Algorithm>,
390	  "algorithm" | "iterations" | "minPasswordlength"
391	> &
392	  Readonly<{
393	    saltBits?: number | undefined;
394	    salt?: string | undefined;
395	    iv?: Uint8Array<ArrayBuffer> | undefined;
396	    ivBits?: number | undefined;
397	    hmac?: boolean | undefined;
398	  }>;
399	
400	/** Generated internal key object. */
401	type Key = Readonly<{
402	  key: CryptoKey;
403	  salt: string;
404	  iv: Uint8Array<ArrayBuffer>;
405	}>;
406	
407	/** Generated HMAC internal results. */
408	type HMacResult = Readonly<{
409	  digest: string;
410	  salt: string;
411	}>;
412	
413	/** Secret object with optional id.*/
414	type PasswordSecret = Readonly<{
415	  id?: string | undefined;
416	  secret: Password;
417	}>;
418	
419	/** Secret object with optional id and specified password for each encryption and integrity. */
420	type PasswordSpecific = Readonly<{
421	  id?: string | undefined;
422	  encryption: Password;
423	  integrity: Password;
424	}>;
425	
426	/** Key-value pairs hash of password id to value. */
427	type PasswordHash = Readonly<Record<string, Password | PasswordSecret | PasswordSpecific>>;
428	
429	export type RawPassword = Password | PasswordSecret | PasswordSpecific;
430

